"""The bio-P level of the plant-wide model (``plantwide_bio_p``), generated by
``examples/plantwide/models/_make_plantwide_bio_p.py``.

Checked against independent references:

- conservation: COD, N, C and P close in every reaction, and the units check
  is clean;
- the PAO's metabolic yields equal those of the shipped TU Delft model
  (``asm2d_tud``), which the PAO is built on: anaerobic PHA and glycogen per
  acetate exactly, aerobic and anoxic growth on PHA to 1%;
- the GAO acetate uptake at pH 7 equals Zeng et al. (2003a, Eq. I), converted
  to g COD, the pH-dependent part included;
- an anaerobic batch: the phosphate released per acetate is ``(1/4 + alpha)``
  P-mol per C-mol, and its gradient in alpha's intercept is the closed form.
"""

from __future__ import annotations

from pathlib import Path

import jax
import jax.numpy as jnp
import numpy as np
import pytest

import aquakin

MODEL = Path(__file__).parents[2] / "examples" / "plantwide" / "models" / "plantwide_bio_p.yaml"
T20, PH = 293.15, 7.0


@pytest.fixture(scope="module")
def biop():
    return aquakin.load_model_from_file(MODEL)


def _row(model, reaction):
    S = np.asarray(model.compute_stoich(model.default_parameters()))
    i = model.reaction_names.index(reaction)
    return {s: float(S[i, j]) for s, j in model.species_index.items()}


def test_every_reaction_conserves_cod_n_c_and_p_and_units_are_clean(biop):
    assert biop.check_conservation() == []
    assert biop.check_units() == []


def test_pao_yields_equal_the_tu_delft_model(biop):
    tud = aquakin.load_model("asm2d_tud")
    p = dict(zip(tud.parameters, np.asarray(tud.default_parameters())))
    ana = _row(biop, "PAO_uptake_of_acetate")
    assert -ana["XGLY_PAO"] == pytest.approx(1 - p["YSA_AN"] + 1, rel=1e-12)  # 0.5
    assert ana["XPHA_PAO_AC"] == pytest.approx(p["YSA_AN"], rel=1e-12)
    aer = _row(biop, "PAO_aerobic_growth_on_PHA_AC")
    assert aer["XPAO"] == pytest.approx(1 / p["YPHA_O"], rel=1e-2)
    anox = _row(biop, "PAO_anoxic_growth_on_PHA_AC")
    assert anox["XPAO"] == pytest.approx(1 / p["YPHA_NO"], rel=1e-2)
    # Nitrate reduced to N2, one for one in N.
    assert anox["SN2"] == pytest.approx(-anox["SNO3"], rel=1e-9)


def test_gao_acetate_uptake_at_ph_7_equals_zeng_eq_i(biop):
    """Zeng et al. (2003a) Eq. I, C-mol per C-mol acetate at pH 7:
    -1.12 glycogen + 1.358 PHB + 0.456 PHV + 0.0367 PH2MV; in g COD (acetate
    and glycogen 32, PHB 36, PHV 38.4, PH2MV 40 per C-mol)."""
    alpha = 0.057 * PH - 0.34
    base = _row(biop, "GAOC_uptake_of_acetate")
    extra = _row(biop, "GAOC_uptake_of_acetate_transport_energy")
    glycogen = -(base["XGLY_GAOC"] + alpha * extra["XGLY_GAOC"])
    pha = base["XPHA_GAOC_AC"] + alpha * extra["XPHA_GAOC_AC"]
    assert glycogen == pytest.approx(1.12, rel=2e-3)
    assert pha == pytest.approx((1.358 * 36 + 0.456 * 38.4 + 0.0367 * 40) / 32, rel=2e-3)


def _anaerobic_batch(biop, acetate):
    """A PAO culture (no GAOs) with full poly-P and glycogen, no O2 or NO3,
    fed `acetate` g COD/m3 at 20 C and pH 7; 0.1 d, long enough to take it all up."""
    C0 = jnp.zeros(biop.n_species)
    for s, v in dict(XPAO=1000.0, XPP=250.0, XGLY_PAO=200.0, SPO4=5.0, SNH4=30.0, SIC=60.0,
                     SA=acetate).items():
        C0 = C0.at[biop.species_index[s]].set(v)
    reactor = aquakin.BatchReactor(
        biop, aquakin.SpatialConditions.uniform(T=T20, pH=PH), rtol=1e-10, atol=1e-10
    )
    return reactor, C0


def test_anaerobic_phosphate_release_per_acetate_and_its_gradient(biop):
    """With and without 100 g COD/m3 of acetate, the extra phosphate released
    is (1/4 + alpha) P-mol per C-mol acetate, alpha = 0.16 pH - 0.7985: times
    31/32 g P per g COD. Its derivative in alpha's intercept is then 31/32 g P
    per g COD of acetate, exactly; reverse mode must give it. Decay and
    anaerobic maintenance are set to zero, so only the uptake differs between
    the runs: decay lyses the PHA made from the acetate back to acetate, taken
    up again (0.09% more release in 0.1 d), and maintenance slows with the
    lower poly-P (3e-5).

    About 11 s, nearly all compiling the reverse-mode solve of the 33-state
    model; it is this level's only gradient check through a solve."""
    S_A0 = 100.0
    k = biop.param_index["alpha_PAO_HAc_int"]

    def release(params, acetate):
        reactor, C0 = _anaerobic_batch(biop, acetate)
        return reactor.solve(C0, t_span=(0.0, 0.1), params=params).C_named("SPO4")[-1]

    p = biop.default_parameters()
    for off in ("b_BIOP", "m_ANA_PAO"):
        p = p.at[biop.param_index[off]].set(0.0)
    extra = float(release(p, S_A0) - release(p, 0.0))
    alpha = 0.16 * PH - 0.7985
    assert extra == pytest.approx((0.25 + alpha) * 31 / 32 * S_A0, rel=1e-6)
    grad = jax.grad(lambda q: release(q, S_A0) - release(q, 0.0))(p)[k]
    assert float(grad) == pytest.approx(31 / 32 * S_A0, rel=1e-6)
    assert jax.config.x64_enabled


def test_a2o_clarifier_settles_every_particulate_of_the_model(biop):
    """``build_a2o`` reads the clarifier's particulates from the model, so the
    plant-wide model's storage pools and acidogens settle with its biomass.
    Fed a stream at 1 g/m3 of everything, the ideal clarifier returns each
    X species to the underflow at capture * Q_in / Q_under and each soluble
    at its inlet concentration."""
    from aquakin.plant import build_a2o
    from aquakin.plant.streams import Stream

    clarifier = build_a2o(biop).units["clarifier"]
    Q_in = 30000.0
    feed = Stream(Q=jnp.asarray(Q_in), C=jnp.ones(biop.n_species), model=biop)
    params = jnp.zeros(0)
    out = clarifier.compute_outputs(0.0, jnp.zeros(0), {"inlet": feed}, params)
    under = out["underflow"]
    thickened = clarifier.capture_efficiency * Q_in / float(under.Q)
    for s, i in biop.species_index.items():
        expected = thickened if s.startswith("X") else 1.0
        assert float(under.C[i]) == pytest.approx(expected, rel=1e-9), s
    assert {"XGLY_PAO", "XPHA_GAOC_PR", "XFE", "XPP"} <= set(clarifier.particulate_species)


POPULATIONS = {
    "PAO": ("XPAO", "XPP", "XGLY_PAO", "XPHA_PAO_AC", "XPHA_PAO_PR"),
    "GAOC": ("XGAOC", "XGLY_GAOC", "XPHA_GAOC_AC", "XPHA_GAOC_PR"),
    "GAOA": ("XGAOA", "XGLY_GAOA", "XPHA_GAOA_AC", "XPHA_GAOA_PR"),
}


@pytest.mark.parametrize("pop", list(POPULATIONS))
@pytest.mark.parametrize("so2", [0.0, 2.0])
def test_a_population_grows_at_the_same_rate_whatever_its_size(biop, pop, so2):
    """Every rate of a PAO or GAO population is proportional to its size: its
    storage switches act on the stored fractions of its biomass, not on
    absolute concentrations. Scaling the population's biomass and pools by
    1e-3, with the bulk liquid unchanged, scales each of its processes' rates
    by 1e-3 exactly, so a rare population (an invader in a plant) grows at the
    same specific rate as an established one. With a Monod switch on an
    absolute pool, the small population's rates fall by up to half."""
    bulk = dict(SA=20.0, SPRO=10.0, SPO4=10.0, SNH4=20.0, SNO3=5.0, SIC=60.0, SO2=so2)
    sizes = dict(XPAO=1000.0, XPP=250.0, XGLY_PAO=150.0, XPHA_PAO_AC=60.0, XPHA_PAO_PR=20.0,
                 XGAOC=800.0, XGLY_GAOC=200.0, XPHA_GAOC_AC=50.0, XPHA_GAOC_PR=10.0,
                 XGAOA=600.0, XGLY_GAOA=150.0, XPHA_GAOA_AC=30.0, XPHA_GAOA_PR=30.0)
    cond = {"T": jnp.asarray([T20]), "pH": jnp.asarray([PH])}
    p = biop.default_parameters()

    def rates(scale):
        state = dict(bulk)
        state.update({s: v * (scale if s in POPULATIONS[pop] else 1.0) for s, v in sizes.items()})
        C = jnp.array([state.get(s, 0.0) for s in biop.species])
        return np.asarray(biop.rates(C, p, cond, 0))

    own = [i for i, name in enumerate(biop.reaction_names) if name.startswith(f"{pop}_")]
    full, small = rates(1.0), rates(1e-3)
    assert np.any(full[own] > 0.0)
    np.testing.assert_allclose(small[own], 1e-3 * full[own], rtol=1e-9, atol=0)
